export function regionOf(state) {
  return Object.keys(REGIONS).find((r) => REGIONS[r].includes(state)) || "Other";
}

export function normalizeDistrictName(s) {
  return (s || "")
    .toUpperCase()
    .replace(/[-–’']/g, " ")
    .replace(/\bFEDERAL\b|\bCONSTITUENCY\b|\bSTATE\b/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

// Given a state + LGA, find the real senatorial district, federal constituency, and any resolvable
// state constituencies that cover it — sourced from the INEC delimitation data (see PRD §6).
export function getCoverage(state, lga) {
  const sen = SEN_DISTRICTS.find(([s, , lgas]) => s === state && lgas.includes(lga));
  const fed = FED_CONSTITUENCIES.find(([s, , lgas]) => s === state && lgas.includes(lga));
  const stateConsts = STATE_CONSTITUENCIES.filter(([s, , lgas]) => s === state && lgas.includes(lga)).map((c) => c[1]);
  return {
    senDistrict: sen ? sen[1] : null,
    fedConstituency: fed ? fed[1] : null,
    stateConstituencies: stateConsts,
  };
}

// Whether a rep's recorded constituency name plausibly matches a real district/constituency name —
// fuzzy/normalized rather than exact, since sample constituency names don't always match official
// spelling precisely (see PRD §6 caveat on this being sample data, not a production-grade join).
export function constituencyMatches(repConstituency, officialName) {
  if (!repConstituency || !officialName) return false;
  const a = normalizeDistrictName(repConstituency);
  const b = normalizeDistrictName(officialName);
  return a === b || a.includes(b) || b.includes(a);
}

export function repCoversArea(rep, state, lga) {
  if (rep.state !== state) return false;
  if (rep.chamber === "Governor") return true; // governors cover the whole state
  const coverage = getCoverage(state, lga);
  if (rep.chamber === "Senate") return constituencyMatches(rep.constituency, coverage.senDistrict);
  if (rep.chamber === "House of Reps") return constituencyMatches(rep.constituency, coverage.fedConstituency);
  if (rep.chamber === "State Assembly") {
    if (coverage.stateConstituencies.length) {
      return coverage.stateConstituencies.some((c) => constituencyMatches(rep.constituency, c));
    }
    return rep.lga === lga; // fallback when state-constituency data doesn't resolve this LGA
  }
  return rep.lga === lga;
}
